parameters.jsCode:
const j = $json;

const message = String(
  j.guardrailsInput ??
  j.chatInput ??
  j.userMessage ??
  j.deidentified_text ??
  j.text ??
  j.message ??
  ""
).trim();

const securityStatus = String(
  j.security_status ?? ""
).toUpperCase();

if (securityStatus !== "ALLOW") {
  return {
    json: {
      ...j,
      riskLevel: "blocked",
      routingReason: "Security check did not return ALLOW",
      routeToModel: false
    }
  };
}

if (!message) {
  return {
    json: {
      ...j,
      riskLevel: "blocked",
      routingReason: "Missing user message",
      routeToModel: false
    }
  };
}

const highRiskPatterns = [
  /\boverdose\b/i,
  /\bpoison(?:ing)?\b/i,
  /\b(can't|cannot|unable to) breathe\b/i,
  /\bshortness of breath\b/i,
  /\bdifficulty breathing\b/i,
  /\bsevere allergic reaction\b/i,
  /\banaphylaxis\b/i,
  /\bchest pain\b/i,
  /\bseizure\b/i,
  /\bunconscious\b/i,
  /\bsevere bleeding\b/i,
  /\btook too much\b/i,
  /\bwrong medication\b/i,
  /\bwrong dose\b/i,
  /\bself[- ]harm\b/i,
  /\bsuicid(?:e|al)\b/i
];

const mediumRiskPatterns = [
  /\bside effects?\b/i,
  /\bdrug interactions?\b/i,
  /\binteractions?\b/i,
  /\bdosage\b/i,
  /\bdose\b/i,
  /\bcontraindications?\b/i,
  /\bpregnan(?:t|cy)\b/i,
  /\bchild(?:ren)?\b/i,
  /\binsulin resistance\b/i,
  /\bmedication safety\b/i,
  /\bmissed dose\b/i,
  /\ballerg(?:y|ies|ic)\b/i,
  /\bchronic disease\b/i
];

let riskLevel = "low";
let routingReason = "General informational request";

if (highRiskPatterns.some(p => p.test(message))) {
  riskLevel = "high";
  routingReason = "Potential urgent or high-risk medical concern";
} else if (mediumRiskPatterns.some(p => p.test(message))) {
  riskLevel = "medium";
  routingReason = "Medical topic requiring more careful review";
}

return {
  json: {
    ...j,
    riskLevel,
    routingReason,
    routeToModel: riskLevel === "low" || riskLevel === "medium"
  }
};

const items = $input.all();

return items.map(item => {
  const j = item.json ?? {};

  const rawRisk = String(
    j.risk_tier ?? j.riskLevel ?? ""
  ).trim().toLowerCase();

  const riskMap = {
    low: "low",
    "low risk": "low",
    medium: "medium",
    "medium risk": "medium",
    high: "high",
    "high risk": "high"
  };

  const riskLevel = riskMap[rawRisk] ?? "unknown";

  const validCaseId =
    typeof j.case_id === "string" &&
    j.case_id.trim().length > 0;

  const validRisk = riskLevel !== "unknown";

  return {
    json: {
      ...j,
      case_id: validCaseId ? j.case_id : null,
      case_summary: j.case_summary ?? "",
      riskLevel,
      review_status: j.review_status ?? "pending",
      routing_valid: validCaseId && validRisk,
      routing_error: !validCaseId
        ? "Missing case_id"
        : !validRisk
          ? "Missing or invalid risk_tier"
          : null
    }
  };
});

const item = $input.item.json;
const text = String(item.request_text || '');
const lowerText = text.toLowerCase().replace(/\s+/g, ' ');

const flags = [];

// Check 1: possible email address
if (/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(text)) {
  flags.push('possible_email');
}

// Check 2: possible phone number
const matches = text.match(/\+?\d[\d\s().-]{6,}\d/g) || [];
if (matches.some(m => m.replace(/\D/g, '').length >= 8)) {
  flags.push('possible_phone');
}

// Check 3: consent must be granted
if (item.consent_status !== 'granted') {
  flags.push('consent_not_granted');
}

// Check 4: suspicious instructions
const suspiciousPatterns = [
  /ignore (all |any |the )?(previous|prior|above|earlier) (instructions|rules)/,
  /disregard (all |any |the )?(previous|prior|above|your) (instructions|rules)/,
  /forget (all |your )?(previous |prior )?(instructions|rules)/,
  /(reveal|show|print|repeat) (your|the) (system )?(prompt|instructions)/,
  /you are now/,
  /pretend (to be|you are)/,
  /act as (a |an )?(doctor|physician|pharmacist|nurse)/,
  /(bypass|override|disable) (the )?(safety|rules|filters|checks)/,
  /developer mode|jailbreak/
];
if (suspiciousPatterns.some(p => p.test(lowerText))) {
  flags.push('suspicious_instruction');
}
// Check 5: possible urgent symptom (demo list, needs clinician approval)
const urgentPatterns = [
  /(can.?t|cannot|unable to) (breathe|speak|talk)/,
  /(struggling|difficulty|trouble) (to |with )?breath/,
  /blue (lips|face|skin)/,
  /(passed out|unconscious|unresponsive|seizure|convuls)/,
  /(emergency|ambulance|urgent)/
];
if (urgentPatterns.some(p => p.test(lowerText))) {
  flags.push('possible_urgent_symptom');
}

// Check 6: request to change a medicine or dose
const medicationChangePatterns = [
  /(stop|skip|double|increase|decrease|reduce|change|lower|raise)\b.{0,30}\b(dose|dosage|medicine|medication|inhaler|insulin|puffs)/,
  /(what|which|how much) (dose|dosage)/
];
if (medicationChangePatterns.some(p => p.test(lowerText))) {
  flags.push('medication_change_request');
}
return {
  json: {
    ...item,
    safety_flags: flags,
    safety_status: flags.length > 0 ? 'review_required' : 'basic_checks_passed'
  }
};

const items = $input.all();

return items.map(item => {
  const data = { ...item.json };

  // Hide the patient's email address
  if (data.email && String(data.email).trim() !== '') {
    data.email = '[EMAIL_REDACTED]';
  }

  return {
    json: {
      ...data,
      emailRedacted: true
    }
  };
});

// Re-identification: map tokens in the LLM output back to real values.
// Reads the mapping from the de-identification node, not from the LLM.
const DEID_NODE = 'De-identify';
const LLM_NODE = 'AI Agent';

const state = $(DEID_NODE).first().json;
const mapping = state.mapping || {};

// --- Pull the model's text out of whatever shape it arrived in ---
const llm = $input.first().json;
let answer =
  llm.content?.[0]?.text            // Anthropic style
  ?? llm.choices?.[0]?.message?.content  // OpenAI style
  ?? llm.output
  ?? llm.text
  ?? llm.message?.content
  ?? (typeof llm === 'string' ? llm : '');

if (typeof answer !== 'string') answer = JSON.stringify(answer);

// --- TTL check: refuse to re-identify an expired mapping ---
const expired = state.expires_at && Date.now() > new Date(state.expires_at).getTime();

// --- Replace tokens, longest first so no token is a prefix of another ---
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const tokens = Object.keys(mapping).sort((a, b) => b.length - a.length);

let restored = answer;
const restoredCounts = {};

for (const token of tokens) {
  // Case-insensitive: models re-emit tokens in altered casing.
  const re = new RegExp(escapeRe(token), 'gi');
  const hits = (restored.match(re) || []).length;
  if (hits > 0) {
    restoredCounts[token] = hits;
    restored = restored.replace(re, mapping[token]);
  }
}

// --- Validate: any surviving token means re-identification failed ---
const residual = restored.match(/\[[A-Z_]+_[A-Z0-9]+_[A-Z0-9]+\]/g) || [];

// --- Leak check: did the model echo a raw value we never gave it? ---
// (Only meaningful if the model was supposed to see tokens only.)
const leaked = Object.values(mapping).filter(v =>
  v.length > 4 && answer.toLowerCase().includes(v.toLowerCase())
);

const ok = !expired && residual.length === 0 && leaked.length === 0;

return [{ json: {
  request_id: state.request_id,
  reidentified: ok,
  answer: ok ? restored : null,
  tokens_in_mapping: tokens.length,
  tokens_restored: Object.keys(restoredCounts).length,
  restored_counts: restoredCounts,
  residual_tokens: residual.length,
  residual_list: residual,
  raw_phi_echoed: leaked.length,
  expired,
  issued_at: state.issued_at,
  expires_at: state.expires_at,
  entity_counts: state.entity_counts,
  recognizers: state.recognizers,
  failure_reason: ok ? null
    : expired ? 'mapping_expired'
    : residual.length ? 'unmapped_tokens_remain'
    : 'raw_phi_in_model_output'
}}];

const items = $input.all();

const suspiciousPatterns = [
  /ignore\s+(all\s+)?previous\s+instructions/i,
  /ignore\s+(all\s+)?(system|developer)\s+instructions/i,
  /reveal\s+(your\s+)?(system\s+)?prompt/i,
  /show\s+(me\s+)?(your\s+)?(hidden\s+)?instructions/i,
  /override\s+(all\s+)?(safety|security|system)\s+(rules|instructions|guidelines)/i,
  /bypass\s+(all\s+)?(safety|security)\s+(rules|filters|checks)/i,
  /disable\s+(all\s+)?(safety|security)\s+(rules|filters|checks)/i,
  /act\s+as\s+(an?\s+)?(unrestricted|unfiltered)\s+(AI|assistant)/i,
  /jailbreak/i,
  /forget\s+(all\s+)?(your\s+)?(previous\s+)?instructions/i
];

return items.map(item => {
  const data = { ...item.json };

  // Inspect user-provided request text fields
  const fieldsToCheck = [
    'request',
    'message',
    'description',
    'question',
    'notes'
  ];

  const textToCheck = fieldsToCheck
    .map(field => data[field])
    .filter(value => typeof value === 'string')
    .join('\n');

  const matchedPatterns = suspiciousPatterns
    .filter(pattern => pattern.test(textToCheck))
    .map(pattern => pattern.source);

  const injectionDetected = matchedPatterns.length > 0;

  return {
    json: {
      ...data,
      injectionDetected,
      injectionStatus: injectionDetected ? 'BLOCK' : 'ALLOW',
      injectionMatches: matchedPatterns
    }
  };
});

const items = $input.all();

const emailRegex = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;

return items.map(item => {
  const email = String(item.json.email ?? '').trim();

  return {
    json: {
      ...item.json,
      email,
      emailValid: emailRegex.test(email)
    }
  };
});

